# Import of required libraries
import skyramp
import os
import re
import time

UUID_PATTERN = r"^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$"
ISO_TIMESTAMP_PATTERN = r"^\d{4}-\d{2}-\d{2}T"

from SkyrampUtils import (
    create_deployment,
    create_deployment_schedule,
    create_flow,
    delete_deployment_schedule,
)


def test_integration():
    # Invocation of Skyramp Client
    client = skyramp.Client()
    # Definition of authentication header
    headers = {}
    if os.getenv("SKYRAMP_TEST_TOKEN") is not None:
        headers["X-Admin-Key"] = os.getenv("SKYRAMP_TEST_TOKEN")

    endpoint_2_POST_response = create_flow(client, headers, "skyramp-sched-guard-flow")

    flow_id = skyramp.get_response_value(endpoint_2_POST_response, "id")
    assert re.match(UUID_PATTERN, str(flow_id), re.IGNORECASE)
    assert str(skyramp.get_response_value(endpoint_2_POST_response, "name")).startswith(
        "skyramp-sched-guard-flow"
    )
    assert re.match(
        ISO_TIMESTAMP_PATTERN,
        str(skyramp.get_response_value(endpoint_2_POST_response, "created")),
    )

    endpoint_1_POST_response = create_deployment(
        client,
        headers,
        "skyramp-sched-guard-deployment",
        flow_id,
    )

    deployment_id = skyramp.get_response_value(endpoint_1_POST_response, "id")
    assert re.match(UUID_PATTERN, str(deployment_id), re.IGNORECASE)
    assert skyramp.get_response_value(endpoint_1_POST_response, "flow_id") == flow_id
    assert str(
        skyramp.get_response_value(endpoint_1_POST_response, "name")
    ).startswith("skyramp-sched-guard-deployment")

    schedules_POST_response = create_deployment_schedule(
        client,
        headers,
        deployment_id,
    )

    schedule_id = skyramp.get_response_value(schedules_POST_response, "0.id")
    assert re.match(UUID_PATTERN, str(schedule_id), re.IGNORECASE)
    assert (
        skyramp.get_response_value(schedules_POST_response, "0.deployment_id")
        == deployment_id
    )
    assert (
        float(skyramp.get_response_value(schedules_POST_response, "0.schedule.interval"))
        == 3600.0
    )
    assert skyramp.get_response_value(schedules_POST_response, "0.active") in (True, "true")
    assert not skyramp.get_response_value(schedules_POST_response, "1.id")

    schedules_schedules_DELETE_response = delete_deployment_schedule(
        client,
        headers,
        deployment_id,
        schedule_id,
    )

    assert (
        skyramp.get_response_value(schedules_schedules_DELETE_response, "detail")
        == "Valid X-Admin-Key header required for this operation."
    )


if __name__ == "__main__":
    test_integration()
